use super::*;
use std::path::Path;
use crate::initializer_policy::{CapturedInitializerEvaluator,InitializerFailure};
struct Source(String);impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok(self.0.clone())}}
fn current(source:String,host:&Arc<dyn dm_tree::frontend::SettingExpressionQueries>,executor:&dm_exec::BuildExecutor)->ColdFrontend{dm_tree::frontend::build_with_executor_and_semantic_state_for_policy_checked(Path::new("original-precheck.dme"),&Source(source),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:None,observer:None},None,executor,None,true,host).unwrap()}
#[test]
fn original_instance_and_constructor_scans_share_actual_admitted_frames_then_same_owner_recovers(){
 let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let length=16;let text=format!("/datum/probe\n    var/value={}\n",vec!["1";length].join("+"));let front=current(text,&host,&executor);let plan=dm_tree::initializers::capture_declaration_plan(&front.snapshot,&front.emission_order).unwrap();let input=front.original_initializer_input(&plan,0).unwrap();let root=input.expression().unwrap();let context=input.declaration_context();let driver=DriverEvaluator{pure_calls:None,resource_search_context:None,resolver:front.snapshot.tree.as_ref(),symbols:front.snapshot.tree.symbols()};let capacity=dm_exec::COMPILER_STACK_BYTES/16/(16*1024);assert!(capacity>=8);
 for scan in 0..3{let failed=scalar_demand::with_admission(&context,|a|{let mut frames=Vec::new();for _ in 0..capacity-4{frames.push(a.evaluation_frame().map_err(InitializerFailure::Operational)?)}
  match scan{0=>driver.instance_call_error_controlled(input.original_write(),root.ast(),&||a.evaluation_frame()).map(|_|()).map_err(InitializerFailure::Operational),1=>driver.constructor_reference_error_controlled(input.original_write(),root.ast(),&||a.evaluation_frame()).map(|_|()).map_err(InitializerFailure::Operational),_=>driver.evaluate_original_write_admitted(&input,input.original_write(),&context,a).map(|_|())}
 });assert!(matches!(failed,Err(InitializerFailure::Operational(ref actual))if actual.kind()==std::io::ErrorKind::OutOfMemory),"scan {scan} must refuse actual stack work, never become a source result");}
 assert_eq!(driver.instance_call_error(input.original_write(),root.ast()),None);assert_eq!(driver.constructor_reference_error(input.original_write(),root.ast()),None);let(value,prepared)=driver.evaluate_original_write_checked(&input,input.original_write()).unwrap();assert!(matches!(value,Evaluation::Scalar(SemanticValue::NumberBits(bits))if bits==(length as f32).to_bits()));assert!(root.same_root(prepared.unwrap().original().unwrap()));assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}
#[test]
fn native_dimension_prechecks_preserve_old_authored_call_source_error(){
 let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let front=current("/datum/probe\n    var/list/items[f()]\n    proc/f()\n        return 1\n".into(),&host,&executor);let bodies=dm_tree::frontend::BodyArena::new_typed(&front,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&front,&[],&executor,&bodies).unwrap();let resolver=startup.resolver(&front,front.snapshot.tree.as_ref()).unwrap();let driver=DriverEvaluator{pure_calls:None,resource_search_context:None,resolver:&resolver,symbols:&startup.plan().symbols};
 let old=crate::initializer_lowering::lower_captured(&front,&startup,&driver,&resolver,None).err().expect("old authored dimension call rejection");let native=crate::initializer_lowering::lower_original_startup(&front,&startup,&driver,&resolver,None).err().expect("native authored dimension call rejection");
 let(crate::initializer_diagnostics::InitializerLoweringError::Diagnostics(old),crate::initializer_diagnostics::InitializerLoweringError::Diagnostics(native))=(old,native)else{panic!("same genuine source diagnostic class")};assert!(!old.is_empty());assert_eq!(old.len(),native.len());for(old,native)in old.iter().zip(&native){assert_eq!(old.kind,native.kind);assert_eq!(old.message,native.message);assert_eq!(old.origin,native.origin);}
}
